"""Tagged cache implementation built on top of :class:`LRUCache`."""

import copy

from . import LRUCache


def _normalize_tags(tags):
    """Validate and deduplicate *tags*, returning a tuple of strings.

    A bare string is rejected, as are non-string entries.  The iterable
    must be finite; any iteration error propagates to the caller.

    """
    if isinstance(tags, str):
        raise ValueError("tags must be an iterable of strings, not a str")
    try:
        iterator = iter(tags)
    except TypeError as exc:
        raise ValueError("tags must be an iterable of strings, got %r" % (tags,)) from exc
    seen = set()
    result = []
    for tag in iterator:
        if not isinstance(tag, str):
            raise ValueError("tags must be an iterable of strings, got %r" % (tag,))
        if tag not in seen:
            seen.add(tag)
            result.append(tag)
    return tuple(result)


class TaggedCache:
    """A tag-aware bounded cache backed by :class:`LRUCache`.

    Values are stored as detached deep copies and values are copied on
    input.  Each entry costs exactly one capacity slot regardless of
    object size.

    """

    def __init__(self, maxsize):
        if isinstance(maxsize, bool) or not isinstance(maxsize, int):
            raise ValueError("maxsize must be a positive integer, got %r" % (maxsize,))
        if maxsize < 1:
            raise ValueError("maxsize must be a positive integer, got %r" % (maxsize,))
        self.__maxsize = maxsize
        self.__data = LRUCache(maxsize)
        # key -> tuple of tags; kept in sync with self.__data
        self.__tags = {}

    @property
    def maxsize(self):
        """The maximum size of the cache."""
        return self.__maxsize

    @property
    def currsize(self):
        """The current number of entries in the cache."""
        return len(self.__data)

    def __len__(self):
        return len(self.__data)

    def __contains__(self, key):
        return key in self.__data

    def put(self, key, value, tags=()):
        """Insert or replace *key* with a deep copy of *value*.

        *tags* must be a finite iterable of strings; duplicate tags are
        removed while preserving first-seen order.  Overwriting an
        existing key replaces its tag memberships and refreshes its LRU
        recency, making it the most-recently-used entry.  Invalid input
        (bad tags or an unhashable key) raises ``ValueError``/``TypeError``
        without changing existing state.

        """
        tag_tuple = _normalize_tags(tags)
        # touching the key validates hashability before any mutation
        existing = key in self.__data
        new_value = copy.deepcopy(value)
        if existing:
            # remove old tag memberships first, then restore recency
            # after the LRU update so replacement tags are not lost
            self.__remove_memberships(key)
            self.__data[key] = new_value
            self.__tags[key] = tag_tuple
            for tag in tag_tuple:
                self.__add_membership(tag, key)
        else:
            self.__data[key] = new_value
            self.__tags[key] = tag_tuple
            for tag in tag_tuple:
                self.__add_membership(tag, key)

    def get(self, key):
        """Return a detached deep copy of the value stored under *key*.

        Refreshes the LRU recency of *key*.  Raises ``KeyError`` for
        missing keys.

        """
        if key not in self.__data:
            raise KeyError(key)
        value = self.__data[key]  # refreshes recency via LRUCache.__getitem__
        return copy.deepcopy(value)

    def invalidate(self, tag):
        """Remove all currently cached entries carrying *tag*.

        Returns the number of entries removed.

        """
        if not isinstance(tag, str):
            raise ValueError("tag must be a string, got %r" % (tag,))
        keys = list(self.__memberships.get(tag, ()))
        for key in keys:
            del self[key]
        return len(keys)

    def __delitem__(self, key):
        if key not in self.__data:
            raise KeyError(key)
        self.__remove_memberships(key)
        del self.__data[key]
        del self.__tags[key]

    def __getitem__(self, key):
        if key not in self.__data:
            raise KeyError(key)
        value = self.__data[key]
        return copy.deepcopy(value)

    def pop(self, key, default=_marker := object()):
        if key in self:
            value = self[key]
            del self[key]
            return value
        elif default is self.pop.__defaults_marker:
            raise KeyError(key)
        return default

    def clear(self):
        """Remove all entries from the cache."""
        self.__data.clear()
        self.__tags.clear()
        self.__memberships.clear()

    def __repr__(self):
        return "TaggedCache(maxsize=%r, currsize=%r)" % (self.__maxsize, len(self))

    # -- internal helpers -------------------------------------------------

    def __add_membership(self, tag, key):
        self.__memberships.setdefault(tag, []).append(key)

    def __remove_memberships(self, key):
        for tag in self.__tags.get(key, ()):
            members = self.__memberships.get(tag)
            if members is not None:
                try:
                    members.remove(key)
                except ValueError:
                    pass
                if not members:
                    del self.__memberships[tag]

    @property
    def __memberships(self):
        # tag -> list of keys; lazily created to keep __init__ simple
        try:
            return self._TaggedCache__memberships_map
        except AttributeError:
            self._TaggedCache__memberships_map = {}
            return self._TaggedCache__memberships_map
